import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[-+*/(),:=<>]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse(content):
        if not content.startswith("="):
            return int(content)

        values = []
        operators = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append((op, left, right))

        for match in token_pattern.finditer(content, 1):
            token = match.group()

            if token[0].isdigit():
                values.append(int(token))
                expect_operand = False
            elif token in functions:
                operators.append((token, len(values)))
                expect_operand = True
            elif token[0].isalpha():
                values.append(token)
                expect_operand = False
            elif token == "(":
                operators.append("(")
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                if operators and isinstance(operators[-1], tuple):
                    name, start = operators.pop()
                    arguments = tuple(values[start:])
                    del values[start:]
                    values.append((name,) + arguments)
                expect_operand = False
            elif token == "-" and expect_operand:
                operators.append("neg")
            else:
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and operators[-1] != "("
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expect_operand = True

        while operators:
            reduce_operator()
        return values[0]

    def argument_nodes(arguments):
        for node in arguments:
            if isinstance(node, tuple) and node[0] == ":":
                first, second = node[1], node[2]
                col1, col2 = sorted((ord(first[0]), ord(second[0])))
                row1, row2 = sorted((int(first[1:]), int(second[1:])))
                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield name
            else:
                yield node

    memo = {}
    active = set()

    for root in cells:
        if root in memo:
            continue

        tasks = [("ref", root)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "ref":
                name = task[1]
                if name in memo:
                    results.append(memo[name])
                elif name not in cells:
                    results.append(0)
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    tasks.append(("save", name))
                    tasks.append(("eval", parse(cells[name])))

            elif kind == "save":
                name = task[1]
                memo[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                if isinstance(node, int):
                    results.append(node)
                elif isinstance(node, str):
                    tasks.append(("ref", node))
                else:
                    op = node[0]
                    if op == "neg":
                        tasks.append(("neg",))
                        tasks.append(("eval", node[1]))
                    elif op == "IF":
                        tasks.append(("choose", node[2], node[3]))
                        tasks.append(("eval", node[1]))
                    elif op in functions:
                        initial = 0 if op == "SUM" else None
                        tasks.append((
                            "aggregate", op, argument_nodes(node[1:]), initial
                        ))
                    else:
                        tasks.append(("left", op, node[2]))
                        tasks.append(("eval", node[1]))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "right":
                op, left = task[1], task[2]
                right = results.pop()

                if isinstance(right, str):
                    value = right
                elif op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        value = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            value = -value
                elif op == "=":
                    value = left == right
                elif op == "<>":
                    value = left != right
                elif op == "<":
                    value = left < right
                elif op == "<=":
                    value = left <= right
                elif op == ">":
                    value = left > right
                else:
                    value = left >= right

                results.append(value)

            elif kind == "choose":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                op, iterator, accumulator = task[1:]
                try:
                    node = next(iterator)
                except StopIteration:
                    results.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("accumulate", op, iterator, accumulator))
                    tasks.append(("eval", node))

            elif kind == "accumulate":
                op, iterator, accumulator = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if op == "SUM":
                        accumulator += value
                    elif accumulator is None:
                        accumulator = value
                    elif op == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("aggregate", op, iterator, accumulator))

    return {name: memo[name] for name in cells}
